import requirementsDocument from "../generated/requirements.json";
import { Badge, PageHeader, Panel } from "../components/Ui";
import { statusLabel } from "../lib/domain";

const toneForStatus = (status: string) => status === "VERIFIED" ? "cyan" : status === "BLOCKED" ? "rose" : status === "IMPLEMENTING" ? "amber" : "neutral";

export function EvidencePage() {
  const requirements = requirementsDocument.requirements;
  const verified = requirements.filter((item) => item.status === "VERIFIED").length;
  return <><PageHeader eyebrow="DELIVERY EVIDENCE" title="Proof before progress" description="Architecture explains intent. Only reproducible tests and external readback can advance a requirement to verified." actions={<Badge tone={verified ? "cyan" : "neutral"}>{verified} / 15 VERIFIED</Badge>} />
    <div className="evidence-summary"><Panel><span>Requirements</span><strong>15</strong><small>Frozen coursework scope</small></Panel><Panel><span>Externally verified</span><strong>{verified}</strong><small>Derived from the YAML ledger</small></Panel><Panel><span>Current public state</span><strong>{verified === 15 ? "Complete" : "In progress"}</strong><small>No UI-only completion claims</small></Panel></div>
    <section className="section-block"><div className="section-heading"><span className="eyebrow">ARCHITECTURE</span><h2>Hybrid execution, explicit authority</h2><p>Cloudflare serves the experience; AWS runs transaction and asynchronous workloads; Sepolia is authoritative for asset and settlement state.</p></div><Panel className="diagram-panel"><img src="/architecture/system-context.svg" alt="Agent Market system architecture showing Cloudflare, AWS, PostgreSQL, queues, ECS, and Sepolia" /><a className="text-link" href="https://github.com/Tiancheng-Xu/agent-market/blob/main/docs/architecture/agent-market-system-context.mmd">View Mermaid source</a></Panel></section>
    <section className="section-block"><div className="section-heading"><span className="eyebrow">REQUEST SEQUENCE</span><h2>One request ID, every boundary</h2><p>State and outbox commit together; consumers are idempotent; chain completion is accepted only after receipt and event verification.</p></div><Panel className="diagram-panel"><img src="/architecture/request-sequence.svg" alt="Request lifecycle sequence across browser, edge, API, database, queues, matcher, and Sepolia" /><a className="text-link" href="https://github.com/Tiancheng-Xu/agent-market/blob/main/docs/architecture/agent-market-request-sequence.mmd">View Mermaid source</a></Panel></section>
    <section className="section-block"><div className="section-heading"><span className="eyebrow">TRACEABILITY MATRIX</span><h2>REQ-AM-01 through REQ-AM-15</h2></div><div className="requirements-list">{requirements.map((item) => <Panel key={item.requirement_id} className="requirement-row"><div className="requirement-title"><span>{item.requirement_id}</span><h3>{item.title}</h3></div><Badge tone={toneForStatus(item.status)}>{statusLabel(item.status)}</Badge><dl><div><dt>Implementation</dt><dd>{item.implementation_locations.length ? item.implementation_locations.join(", ") : "-"}</dd></div><div><dt>Tests</dt><dd>{item.test_evidence.length ? item.test_evidence.join(", ") : "-"}</dd></div><div><dt>Deployment</dt><dd>{item.deployment_evidence.length ? item.deployment_evidence.join(", ") : "-"}</dd></div><div><dt>Transaction</dt><dd>{item.transaction_evidence.length ? item.transaction_evidence.join(", ") : "-"}</dd></div><div><dt>Last verified</dt><dd>{item.last_verified_at ?? "-"}</dd></div></dl></Panel>)}</div></section>
    <section className="section-block"><div className="section-heading"><span className="eyebrow">EXTERNAL PROOF</span><h2>AWS and delivery screenshots</h2></div><Panel className="evidence-placeholder"><span className="empty-mark">0</span><h3>No sanitized external screenshots yet</h3><p>AWS screenshots will be added only after account/region readback, project ownership verification, successful runtime validation, and redaction. The same run will record subsequent suspension or cleanup.</p></Panel></section>
    <section className="limitations"><Panel><h2>Current limitations</h2><ul><li>No AWS workload has been deployed or read back.</li><li>No Cloudflare production deployment has been verified.</li><li>No Sepolia task escrow or settlement transaction exists yet.</li><li>Stitch fixtures are design references, not project evidence.</li></ul></Panel><Panel><h2>Reproduce locally</h2><pre><code>pnpm install --frozen-lockfile{`\n`}pnpm verify{`\n`}pnpm --filter @agent-market/web build</code></pre><a className="text-link" href="https://github.com/Tiancheng-Xu/agent-market">Open repository</a></Panel></section>
  </>;
}
